//! Material 3 design tokens.
//!
//! Every value here comes from the Jetpack Compose material3 token files
//! (`androidx.compose.material3.tokens` on `androidx-main`); each item names
//! the token it mirrors. The baseline token set is implemented; where M3
//! Expressive adds tokens (emphasized type, expressive springs, the
//! increased corner sizes) they are included and say so.
//!
//! The baseline colour tables are generated by `tools/gen_color_tokens.mjs`;
//! the rest are short enough to keep by hand.

mod baseline;
pub mod color;
pub mod elevation;
pub mod motion;
pub mod shape;
pub mod state;
pub mod typography;

pub use color::{ColorRole, ColorScheme};
pub use elevation::Elevation;
pub use motion::{animate_value_with_spring, CubicBezier, MotionScheme, SpringSpec, SpringSpeed};
pub use shape::{CornerSize, Corners, LayoutDirection, Shape};
pub use state::InteractionState;
pub use typography::{TypeRole, TypeStyle};
